const fs = require('fs');

if (!fs.existsSync('input.txt')) {
  console.error('ERROR: falta input.txt (una línea con el nombre del proyecto)');
  process.exit(2);
}
const name = fs.readFileSync('input.txt', 'utf8').trim();
fs.mkdirSync('dist', { recursive: true });
fs.writeFileSync('dist/out.txt', `built ${name}\n`);
console.log('build ok');
